 void DofusPage(StackPanel body){
  var intro=new StackPanel();intro.Children.Add(T("Les parcours Tougli dans votre espace, avec une progression locale par personnage. Les étapes se valident manuellement ; aucun compte Tougli n’est connecté.",12,Muted,new Thickness(0,0,0,14)));var tools=new WrapPanel();tools.Children.Add(Btn("+ Personnage",()=>EditDofusCharacter(null),true));var character=DofusCompanion.Character(store.Value);if(character!=null)tools.Children.Add(Btn("Modifier ce personnage",()=>EditDofusCharacter(character),false,true));var catalogue=Btn(dofusBusy?"Chargement…":"Charger le catalogue Tougli",LoadDofusCatalogue,false,true);catalogue.IsEnabled=!dofusBusy;tools.Children.Add(catalogue);tools.Children.Add(Btn("Vue compacte",ShowDofusOverlay,false,true));if(dofusBusy)tools.Children.Add(Btn("Annuler",()=>{if(dofusCancel!=null)dofusCancel.Cancel();},false,true));intro.Children.Add(tools);body.Children.Add(Card("Votre compagnon de jeu",intro));
