  var guides=dofusCatalogue.ToList();if(!guides.Any(g=>g.Slug==character.guide))guides.Add(new TougliGuideInfo{Slug=character.guide,Title=character.guide});var guidePanel=new StackPanel();var guide=Combo(guides.Select(g=>g.Title),guides.First(g=>g.Slug==character.guide).Title);Field(guidePanel,"Parcours Tougli",guide);guide.SelectionChanged+=delegate{if(guide.SelectedIndex>=0)DofusChange(()=>DofusCompanion.Character(store.Value).guide=guides[guide.SelectedIndex].Slug);};Grid.SetColumn(guidePanel,1);choices.Children.Add(guidePanel);body.Children.Add(choices);
  var doc=CurrentDofusDocument();var actions=new WrapPanel{Margin=new Thickness(0,0,0,18)};var load=Btn(doc==null?"Charger ce guide":"Actualiser ce guide",DownloadDofusGuide,true);load.IsEnabled=!dofusBusy;actions.Children.Add(load);var instructions=Btn("Charger les instructions Ganymède",LoadDofusInstructions,false,true);instructions.IsEnabled=!dofusBusy&&doc!=null;actions.Children.Add(instructions);var associate=Btn("Associer un guide Ganymède",AssociateDofusInstructions,false,true);associate.IsEnabled=!dofusBusy;actions.Children.Add(associate);actions.Children.Add(Btn("Ouvrir Tougli",()=>Open(TougliReader.Site+"/guide/"+character.guide),false,true));body.Children.Add(actions);if(doc==null){body.Children.Add(T("Chargez le guide choisi pour afficher ses étapes. Un guide déjà chargé reste consultable hors ligne sur ce PC.",14,Muted));return;}
  body.Children.Add(T(doc.Title,23,Ink,new Thickness(0,0,0,10)));if(doc.Description!="")body.Children.Add(T(doc.Description,12,Muted,new Thickness(0,0,0,15)));var progress=DofusCompanion.Find(store.Value,character);int done=doc.Steps.Count(s=>progress!=null&&progress.done.Contains(s.Key));body.Children.Add(T(done+" / "+doc.Steps.Count+" étapes validées · "+Math.Round(100.0*done/doc.Steps.Count)+" %",12,Accent));body.Children.Add(new ProgressBar{Maximum=doc.Steps.Count,Value=done,Height=5,Foreground=Accent,Background=FaintLine,Margin=new Thickness(0,8,0,20)});if(progress!=null&&progress.done.Any(k=>!doc.Steps.Any(s=>s.Key==k)))body.Children.Add(T("Certaines anciennes étapes ne correspondent plus au guide ou aux choix actuels. Leur validation n’a pas été attribuée à d’autres étapes.",11,Accent,new Thickness(0,0,0,14)));
  var step=DofusCompanion.Current(store.Value,doc);if(step!=null){var panel=new StackPanel();panel.Children.Add(T(step.Section,11,Accent,new Thickness(0,0,0,10)));panel.Children.Add(DofusPositionText(T(step.Details==""?"Consultez le guide détaillé pour les instructions de la quête.":step.Details,13,Muted,new Thickness(0,0,0,14))));if(step.Resources.Count>0){panel.Children.Add(T("RESSOURCES DE CETTE QUÊTE",10,Accent));foreach(var r in step.Resources.Take(100))panel.Children.Add(T(r.Count+" × "+r.Name,12,Ink,new Thickness(0,5,0,0)));}var instructionPanel=DofusInstructionPanel(step);if(instructionPanel!=null)panel.Children.Add(instructionPanel);var row=new WrapPanel{Margin=new Thickness(0,15,0,0)};row.Children.Add(Btn("Précédent",()=>DofusStepAction(-1,false),false,true));var finish=Btn("Terminé →",()=>DofusStepAction(1,true),true);finish.IsEnabled=step.CanComplete;row.Children.Add(finish);row.Children.Add(Btn("Suivant",()=>DofusStepAction(1,false),false,true));if(step.CanComplete)row.Children.Add(Btn(progress!=null&&progress.done.Contains(step.Key)?"Annuler la validation":"Valider sans avancer",DofusToggle,false,true));else row.Children.Add(Btn("Renseigner mon personnage",()=>EditDofusCharacter(character),false,true));panel.Children.Add(row);var links=new WrapPanel{Margin=new Thickness(0,10,0,0)};links.Children.Add(Btn("Guide détaillé",()=>Open(step.Url),false,true));if(step.Coordinates!="")links.Children.Add(Btn("Copier /travel",()=>CopyDofusTravel(step),false,true));links.Children.Add(Btn("Ressources restantes",DofusRemainingResources,false,true));panel.Children.Add(links);body.Children.Add(Card(step.Title,panel));}
  var search=new TextBox{Text=dofusSearch,MaxLength=180};Field(body,"Retrouver une étape",search);var list=DofusStepList();Action filter=delegate{dofusSearch=search.Text;list.ItemsSource=doc.Steps.Where(s=>(s.Title+" "+s.Section).IndexOf(dofusSearch,StringComparison.CurrentCultureIgnoreCase)>=0).ToList();};search.TextChanged+=delegate{filter();};filter();body.Children.Add(list);body.Children.Add(Btn("Aller à l’étape sélectionnée",delegate{var selectedStep=list.SelectedItem as TougliStep;if(selectedStep!=null)DofusChange(()=>DofusCompanion.Get(store.Value,DofusCompanion.Character(store.Value)).cursor=selectedStep.Key);},false,true));body.Children.Add(T("Source : Tougli — Toufloux et Gligo. Chargement public à la demande, sans synchronisation de compte. Les liens détaillés utilisent votre navigateur habituel. Les choix non reconnus restent à consulter sur Tougli.",11,Muted,new Thickness(0,12,0,0)));
