 ListBox DofusStepList(){var list=new ListBox{Height=220,Margin=new Thickness(0,6,0,12),Background=SurfaceBrush,Foreground=Ink,BorderBrush=FaintLine,BorderThickness=new Thickness(1),Padding=new Thickness(5)};var text=new FrameworkElementFactory(typeof(TextBlock));text.SetBinding(TextBlock.TextProperty,new System.Windows.Data.Binding("Display"));text.SetValue(TextBlock.TextWrappingProperty,TextWrapping.Wrap);text.SetValue(TextBlock.FontSizeProperty,12.0);list.ItemTemplate=new DataTemplate{VisualTree=text};var style=new Style(typeof(ListBoxItem));style.Setters.Add(new Setter(Control.ForegroundProperty,Ink));style.Setters.Add(new Setter(Control.BackgroundProperty,System.Windows.Media.Brushes.Transparent));style.Setters.Add(new Setter(Control.HorizontalContentAlignmentProperty,HorizontalAlignment.Stretch));var border=new FrameworkElementFactory(typeof(Border));border.SetValue(Border.CornerRadiusProperty,new CornerRadius(8));border.SetValue(Border.PaddingProperty,new Thickness(9));border.SetBinding(Border.BackgroundProperty,new System.Windows.Data.Binding("Background"){RelativeSource=new System.Windows.Data.RelativeSource(System.Windows.Data.RelativeSourceMode.TemplatedParent)});border.AppendChild(new FrameworkElementFactory(typeof(ContentPresenter)));var template=new ControlTemplate(typeof(ListBoxItem)){VisualTree=border};var selected=new Trigger{Property=ListBoxItem.IsSelectedProperty,Value=true};selected.Setters.Add(new Setter(Control.BackgroundProperty,SelectionBrush));template.Triggers.Add(selected);style.Setters.Add(new Setter(Control.TemplateProperty,template));list.ItemContainerStyle=style;return list;}
 void DofusStepAction(int direction,bool complete){if(store.Value.settings.PrivacyMode)return;var doc=CurrentDofusDocument();try{DofusCompanion.Navigate(store,doc,direction,complete);}catch(Exception ex){MessageBox.Show(ex.Message,"Progression Dofus");}Refresh();UpdateDofusOverlay();}
 void DofusToggle(){if(store.Value.settings.PrivacyMode)return;try{DofusCompanion.Toggle(store,CurrentDofusDocument());}catch(Exception ex){MessageBox.Show(ex.Message,"Progression Dofus");}Refresh();UpdateDofusOverlay();}
 void CopyDofusTravel(TougliStep step){if(store.Value.settings.PrivacyMode||owner.IsPreview||step==null||step.Coordinates=="")return;try{Clipboard.SetText("/travel "+step.Coordinates);}catch(Exception ex){MessageBox.Show(ex.Message);}}
 void DofusRemainingResources(){var doc=CurrentDofusDocument();if(doc==null)return;StackPanel body,actions;var w=Dialog("Ressources des quêtes restantes",out body,out actions,700);body.Children.Add(T("Somme des quantités indiquées par Tougli, par quête non validée. Les quêtes répétées ne sont comptées qu’une fois ; votre inventaire et les ressources déjà consommées ne sont pas connus.",12,Muted,new Thickness(0,0,0,16)));foreach(var r in DofusCompanion.Remaining(store.Value,doc))body.Children.Add(T(r.Count+" × "+r.Name,13,Ink,new Thickness(0,4,0,4)));actions.Children.Add(Btn("Fermer",delegate{w.Close();},false,true));ShowWindow(w);}
 void EditDofusCharacter(DofusCharacter existing){StackPanel body,actions;var w=Dialog(existing==null?"Ajouter mon personnage":"Modifier mon personnage",out body,out actions,730);var name=new TextBox{Text=existing==null?"":existing.name,MaxLength=60};Field(body,"Nom",name);var server=new TextBox{Text=existing==null?"":existing.server,MaxLength=60};Field(body,"Serveur (facultatif)",server);var type=Combo(DofusCompanion.ClassNames,DofusCompanion.ClassNames[existing==null?0:Array.IndexOf(DofusCompanion.Classes,existing.classCode)]);Field(body,"Classe",type);var alignCodes=new[]{"","Neutre","Bonta","Brak"};var alignNames=new[]{"Non renseigné","Neutre","Bontarien","Brâkmarien"};var align=Combo(alignNames,alignNames[existing==null?0:Array.IndexOf(alignCodes,existing.alignment)]);Field(body,"Alignement",align);var orderCodes=new[]{"","CV","OA","ES","CS","OP","EM"};var orderNames=new[]{"Non renseigné","CV · Cœur Vaillant","OA · Œil Attentif","ES · Esprit Salvateur","CS · Cœur Saignant","OP · Œil Putride","EM · Esprit Malsain"};var order=Combo(orderNames,orderNames[existing==null?0:Array.IndexOf(orderCodes,existing.order)]);Field(body,"Ordre d’alignement",order);body.Children.Add(T("Les choix du guide utilisent uniquement ces informations. Ils ne sont pas récupérés depuis le jeu.",11,Muted));var error=T("",12,Accent);body.Children.Add(error);actions.Children.Add(Btn("Annuler",delegate{w.Close();},false,true));actions.Children.Add(Btn("Enregistrer",delegate{try{if(String.IsNullOrWhiteSpace(name.Text))throw new InvalidDataException("Donnez un nom au personnage.");if(store.Value.dofus.characters.Any(p=>(existing==null||p.id!=existing.id)&&String.Equals(p.name,name.Text.Trim(),StringComparison.CurrentCultureIgnoreCase)&&String.Equals(p.server,server.Text.Trim(),StringComparison.CurrentCultureIgnoreCase)))throw new InvalidDataException("Ce personnage existe déjà sur ce serveur.");var c=new DofusCharacter{id=existing==null?Guid.NewGuid().ToString():existing.id,name=name.Text.Trim(),server=server.Text.Trim(),classCode=DofusCompanion.Classes[type.SelectedIndex],alignment=alignCodes[align.SelectedIndex],order=orderCodes[order.SelectedIndex],guide=existing==null?"rsa-rush-sylvestre-accelere":existing.guide};PersonalWorkflows.Change(store,()=>{store.Value.dofus.characters.RemoveAll(p=>p.id==c.id);store.Value.dofus.characters.Add(c);store.Value.dofus.active=c.id;});dofusDocumentKey="";FinishFinanceDialog(w);}catch(Exception ex){error.Text=ex.Message;}},true));ShowWindow(w);Refresh();UpdateDofusOverlay();}
 async void DofusOperation(Func<ApplicationUpdates,CancellationToken,Task> action){if(dofusBusy||owner.IsPreview)return;dofusBusy=true;dofusCancel=new CancellationTokenSource();Refresh();ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;try{using(var http=new HttpClient(new HttpClientHandler{AllowAutoRedirect=false}){Timeout=TimeSpan.FromSeconds(45)})await action(new ApplicationUpdates(http),dofusCancel.Token);}catch(OperationCanceledException){dofusMessage="Chargement du guide annulé. Votre progression est conservée.";}catch(Exception ex){dofusMessage="Le guide n’a pas pu être chargé : "+ex.Message+" Votre dernier guide local et votre progression sont conservés.";}finally{dofusBusy=false;dofusCancel.Dispose();dofusCancel=null;if(!owner.IsDisposed){Refresh();UpdateDofusOverlay();}}}
 void LoadDofusCatalogue(){DofusOperation(async(client,token)=>{var bytes=await client.Read(TougliReader.Api+"/api/guide/list",TougliReader.MaxBytes,token);var catalogue=TougliReader.Catalogue(Encoding.UTF8.GetString(bytes));token.ThrowIfCancellationRequested();dofusCatalogue.Clear();dofusCatalogue.AddRange(catalogue.OrderBy(g=>g.Slug=="rsa-rush-sylvestre-accelere"?0:1).ThenBy(g=>g.Title));dofusMessage="Catalogue chargé · "+catalogue.Count+" guides. Choisissez un parcours puis chargez-le.";});}
 void DownloadDofusGuide(){var character=DofusCompanion.Character(store.Value);if(character==null)return;string key=DofusDocumentKey(),slug=character.guide;DofusOperation(async(client,token)=>{var bytes=await client.Read(TougliReader.Api+"/api/guide/details/"+slug,TougliReader.MaxBytes,token);string json=Encoding.UTF8.GetString(bytes);var doc=TougliReader.Parse(json,character);if(doc.Slug!=slug)throw new InvalidDataException("Le serveur a renvoyé un autre parcours.");token.ThrowIfCancellationRequested();TougliReader.Cache(store,slug,json);if(key==DofusDocumentKey()){dofusDocument=doc;dofusDocumentKey=key;}dofusMessage="Guide chargé · "+doc.Steps.Count+" étapes pour les choix de ce personnage. Les validations restent locales.";});}
 void UpdateDofusOverlay(){if(dofusOverlay!=null)dofusOverlay.RefreshView();}
 void ShowDofusOverlay(){if(owner.IsPreview)return;if(dofusOverlay!=null){dofusOverlay.Show();dofusOverlay.Activate();return;}dofusOverlay=new DofusOverlay(owner,store,CurrentDofusDocument,()=>{owner.ShowWorkspaceFromWidget();Go("Compagnon Dofus");},DofusStepAction,DofusToggle,CopyDofusTravel,DofusInstructionPanel,DofusInstructionSignature);dofusOverlay.Closed+=delegate{dofusOverlay=null;};dofusOverlay.Show();}
 internal void CloseDofusCompanion(){if(dofusCancel!=null)dofusCancel.Cancel();if(dofusOverlay!=null){var overlay=dofusOverlay;dofusOverlay=null;overlay.Close();}}
 Action DofusModeFields(StackPanel body,LaunchMode draft){var codes=new[]{"auto","off","page","overlay","both"};var names=new[]{"Automatique · page et vue compacte pour Dofus","Ne pas ouvrir le compagnon","Page du compagnon","Vue compacte uniquement","Page et vue compacte"};var input=Combo(names,names[Math.Max(0,Array.IndexOf(codes,draft.dofusView))]);Field(body,"Compagnon Dofus à la fin du lancement",input);body.Children.Add(T("Le suivi est local. Si le mode ouvre déjà Tougli dans le navigateur, retirez cette ancienne action si elle fait doublon.",11,Muted));return ()=>draft.dofusView=codes[input.SelectedIndex];}
 void FinishDofusMode(LaunchMode mode,bool keepPage){string view=mode.dofusView=="auto"?((mode.homePreset=="Dofus"||String.Equals(mode.name,"Dofus",StringComparison.CurrentCultureIgnoreCase))?"both":"off"):mode.dofusView;if((view=="page"||view=="both")&&!keepPage&&String.IsNullOrEmpty(mode.pageKind))Go("Compagnon Dofus");if(view=="overlay"||view=="both")ShowDofusOverlay();}
